"""Weak-topic memory: aggregated from saved sessions and stored as a readable markdown table."""

from __future__ import annotations

import difflib
from dataclasses import dataclass

WEAK_THRESHOLD = 6.0
HEADER = [
    "# Weak topics",
    "",
    "<!-- Generated by MockMate from workspace/sessions/. Topics averaging below 6.0 count as weak. -->",
    "",
    "| Round | Topic | Attempts | Avg score | Last seen |",
    "|---|---|---|---|---|",
]


@dataclass
class TopicStat:
    round: str
    topic: str
    attempts: int
    avg: float
    last_seen: str


def _clean(s: str) -> str:
    return s.replace("|", "/").strip()


def aggregate(sessions: list[tuple[dict, list[dict]]]) -> list[TopicStat]:
    acc: dict[tuple[str, str], dict] = {}
    for meta, records in sessions:
        rnd = meta.get("round", "")
        for r in records:
            key = (rnd.lower(), r["topic"].strip().lower())
            slot = acc.setdefault(key, {"round": rnd, "topic": r["topic"].strip(), "scores": [], "last": ""})
            slot["scores"].append(r["card"]["score"])
            slot["last"] = max(slot["last"], meta.get("date", ""))
    stats = [
        TopicStat(v["round"], v["topic"], len(v["scores"]), round(sum(v["scores"]) / len(v["scores"]), 1), v["last"])
        for v in acc.values()
    ]
    return sorted(stats, key=lambda s: (s.avg, s.topic.lower()))


def render(stats: list[TopicStat]) -> str:
    rows = [
        f"| {_clean(s.round)} | {_clean(s.topic)} | {s.attempts} | {s.avg:.1f} | {s.last_seen} |" for s in stats
    ]
    return "\n".join(HEADER + rows) + "\n"


def parse(text: str) -> list[TopicStat]:
    stats = []
    for ln in text.splitlines():
        if not ln.startswith("|"):
            continue
        cells = [c.strip() for c in ln.strip().strip("|").split("|")]
        if len(cells) != 5 or not cells[2].isdigit():
            continue  # header / separator
        try:
            stats.append(TopicStat(cells[0], cells[1], int(cells[2]), float(cells[3]), cells[4]))
        except ValueError:
            continue
    return stats


def weak_for_round(stats: list[TopicStat], round_name: str) -> list[str]:
    return [s.topic for s in stats if s.round.lower() == round_name.lower() and s.avg < WEAK_THRESHOLD]


def drop_topics(content: str, drop: list[str]) -> str:
    """Used by the 'edit' approval choice: remove the named topics from the proposed table."""
    gone = {d.strip().lower() for d in drop if d.strip()}
    kept = []
    for ln in content.splitlines():
        cells = [c.strip() for c in ln.strip().strip("|").split("|")] if ln.startswith("|") else []
        if len(cells) == 5 and cells[2].isdigit() and cells[1].lower() in gone:
            continue
        kept.append(ln)
    return "\n".join(kept) + "\n"


def make_diff(old: str, new: str, limit: int = 40) -> str:
    lines = list(
        difflib.unified_diff(
            old.splitlines(), new.splitlines(), "weak-topics.md (current)", "weak-topics.md (proposed)", lineterm=""
        )
    )
    if len(lines) > limit:
        lines = lines[:limit] + [f"... ({len(lines) - limit} more lines)"]
    return "\n".join(lines)
